// ─── Recursive Markdown Text Splitter ─────────────────────────────────────────
// Replica o comportamento do LangChain/n8n RecursiveCharacterTextSplitter
// ─────────────────────────────────────────────────────────────────────────────
const MARKDOWN_SEPARATORS = [
  "\n## ", "\n### ", "\n#### ", "\n##### ", "\n###### ",
  "\n\n", "\n", " ", ""
];
const chunkSize    = 1000;
const chunkOverlap = 0;

// ── Etapa 1: split recursivo (igual ao seu, só ajuste no rebuild do separador)
function splitRecursively(text, separators) {
  if (!text || text.trim() === "") return [];

  let usedSep = "";
  let newSeps = [];
  let rawSplits = [];

  for (let i = 0; i < separators.length; i++) {
    const sep = separators[i];
    if (sep === "") {
      rawSplits = text.split("");
      usedSep = "";
      newSeps = [];
      break;
    }
    if (text.includes(sep)) {
      usedSep = sep;
      newSeps = separators.slice(i + 1);
      const escaped = sep.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      rawSplits = text.split(new RegExp(`(?=${escaped})`));
      break;
    }
  }

  if (rawSplits.length === 0) return [text];

  const results = [];
  for (const part of rawSplits) {
    if (!part || part.trim() === "") continue;
    if (part.length <= chunkSize) {
      results.push(part);
    } else if (newSeps.length > 0) {
      results.push(...splitRecursively(part, newSeps));
    } else {
      results.push(part); // força manter mesmo sendo grande
    }
  }
  return results;
}

function mergeChunks(splits, separator) {
  const chunks = [];
  let currentParts = [];
  let currentLen = 0;
  const sepLen = separator.length;

  for (const split of splits) {
    const splitLen = split.length;

    // Se adicionar esse split estoura o chunkSize, fecha o chunk atual
    if (currentLen + splitLen + (currentParts.length > 0 ? sepLen : 0) > chunkSize) {
      if (currentParts.length > 0) {
        const chunk = currentParts.join(separator).trim();
        if (chunk) chunks.push(chunk);

        // ── Overlap: mantém partes do final para o próximo chunk
        while (
          currentParts.length > 0 &&
          (currentLen > chunkOverlap ||
            (currentLen + splitLen + sepLen > chunkSize && currentLen > 0))
        ) {
          currentLen -= currentParts[0].length + (currentParts.length > 1 ? sepLen : 0);
          currentParts.shift();
        }
      }
    }

    currentParts.push(split);
    currentLen += splitLen + (currentParts.length > 1 ? sepLen : 0);
  }

  // flush do último chunk
  if (currentParts.length > 0) {
    const chunk = currentParts.join(separator).trim();
    if (chunk) chunks.push(chunk);
  }

  return chunks;
}

// ── Pipeline completo
function splitMarkdown(text) {
  const splits = splitRecursively(text, MARKDOWN_SEPARATORS);
  // O merge usa "" como separador (os splits já carregam o separador embutido)
  return mergeChunks(splits, "");
}

// ─── Lógica principal do nó ───────────────────────────────────────────────────
const items = $input.all();
const output = [];

for (const item of items) {
  const text = item.json.text || item.json.content || item.json.pageContent || "";
  if (!text) continue;

  const chunks = splitMarkdown(text);

  for (let chunkIdx = 0; chunkIdx < chunks.length; chunkIdx++) {
    const chunk = chunks[chunkIdx];
    output.push({
      json: {
        text: chunk,
        metadata: {
          chunkIndex: chunkIdx,
          chunkTotal: chunks.length,
          chunkSize: chunk.length,
          ...$input.first().json.metadata
        }
      }
    });
  }
}

return output;

function extractContent(documents) {
  let content = "";

  for (const doc of documents) {
    // Adiciona o markdown
    if (doc.markdown) {
      content += doc.markdown + "\n\n";
    }

    // Substitui as referências [tbl-x.html] pelo conteúdo real da tabela
    if (doc.tables && doc.tables.length > 0) {
      for (const table of doc.tables) {
        content = content.replace(
          `[${table.id}](${table.id})`,
          table.content
        );
      }
    }
  }

  return content.trim();
}

